import{c as a,Q as t,j as n,m as r}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"A Language for Describing Agentic LLM Contexts","description":"","frontmatter":{"url":"https://arxiv.org/abs/2605.01920","title":"A Language for Describing Agentic LLM Contexts","arxiv_id":2605.0192,"collected_at":"2026-08-04T00:00:00.000Z","collected_by":"routine-d","domain":"Context Engineering","pdf_path":"pdfs/2605.01920.pdf","year":2026},"headers":[],"relativePath":"research/papers/2026-08-04-language-describing-agentic-llm-contexts-acdl-2605-01920.md","filePath":"research/papers/2026-08-04-language-describing-agentic-llm-contexts-acdl-2605-01920.md","lastUpdated":1785909234000}'),i={name:"research/papers/2026-08-04-language-describing-agentic-llm-contexts-acdl-2605-01920.md"};function s(c,e,o,g,l,d){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="a-language-for-describing-agentic-llm-contexts" tabindex="-1">A Language for Describing Agentic LLM Contexts <a class="header-anchor" href="#a-language-for-describing-agentic-llm-contexts" aria-label="Permalink to &quot;A Language for Describing Agentic LLM Contexts&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>作者指出 LLM agent 系統目前多用非正式散文、隨手畫的圖或直接讀程式碼來說明其 prompt 組成方式，缺乏標準化表示法。論文提出 ACDL（Agentic Context Description Language），提供精確、可讀、標準的方式描述 LLM 輸入 context 如何在互動步驟間建構與演變。ACDL 支援角色訊息、動態內容、時間索引參照與條件結構，且獨立於實作細節。作者以多個系統範例示範 ACDL 用法，並鼓勵在學術論文與實務開發中採用，文件與工具已公開。</p><h2 id="與-harness-的關聯" tabindex="-1">與 Harness 的關聯 <a class="header-anchor" href="#與-harness-的關聯" aria-label="Permalink to &quot;與 Harness 的關聯&quot;">​</a></h2><p>呼應 core.md「References &gt; 散文 spec」原則的反向命題：本文提出的是「context 組成本身」的標準化描述語言，可作為未來若要讓 sub-agent brief 或 skill 的 context 組成方式可機械稽核（而非僅靠散文描述）時的形式化參考。</p>',5)])])}const _=a(i,[["render",s]]);export{u as __pageData,_ as default};
